// src/stores/session/board-session-reducer.ts
import type { BoardRules } from './board-rules';

export type BoardSession = { readonly cells: readonly boolean[]; readonly moves: number };
export type BoardAction = { readonly type: 'press'; readonly cell: number };

export function boardSessionReducer(rules: BoardRules, session: BoardSession, action: BoardAction): BoardSession {
  if (action.cell < 0 || action.cell >= rules.size) return session;
  return { cells: rules.press(session.cells, action.cell), moves: session.moves };
}

// src/stores/session/board-rules.ts
export type BoardRules = { readonly size: number; readonly press: (cells: readonly boolean[], cell: number) => readonly boolean[] };

export const TOGGLE_RULES: BoardRules = {
  size: 3,
  press: (cells, cell) => cells.map((on, index) => (Math.abs(index - cell) <= 1 ? !on : on)),
};

// src/stores/session/board-session-reducer-cases.ts
import type { ReducerCases } from '@/stores/reducer-cases';

import type { BoardAction, BoardSession } from './board-session-reducer';

export { TOGGLE_RULES } from './board-rules';

export const BOARD_SESSION_REDUCER_CASES: ReducerCases<BoardSession, BoardAction> = {
  reducer: 'boardSessionReducer',
  rules: 'TOGGLE_RULES',
  initial: { cells: [false, false, false], moves: 0 },
  cases: [
    { rule: 'press-toggles-neighbours', action: { type: 'press', cell: 0 }, expect: { cells: [true, true, false], moves: 1 } },
    { rule: 'press-outside-is-a-no-op', action: { type: 'press', cell: 7 }, same: true },
  ],
};

