// src/stores/settings/settings-reducer.ts
export type Settings = { readonly theme: 'system' | 'light' | 'dark' };
export type SettingsAction = { readonly type: 'set-theme'; readonly theme: Settings['theme'] };

export function settingsReducer(settings: Settings, action: SettingsAction): Settings {
  return settings.theme === action.theme ? settings : { ...settings, theme: action.theme };
}

